from django.db import models
class Base(models.Model):
 empresa=models.ForeignKey("conduces.Empresa",on_delete=models.CASCADE);creado_en=models.DateTimeField(auto_now_add=True)
 class Meta:abstract=True
class TipoNomina(Base):nombre=models.CharField(max_length=100);periodicidad=models.CharField(max_length=15)
class PeriodoNomina(Base):tipo=models.ForeignKey(TipoNomina,on_delete=models.PROTECT);desde=models.DateField();hasta=models.DateField();estado=models.CharField(max_length=15,default="ABIERTO")
class ConceptoNomina(Base):codigo=models.CharField(max_length=20);nombre=models.CharField(max_length=120);tipo=models.CharField(max_length=12,choices=[("INGRESO","Ingreso"),("DEDUCCION","Deducción"),("APORTE","Aporte")]);gravable=models.BooleanField(default=False)
class ReglaNomina(Base):concepto=models.ForeignKey(ConceptoNomina,on_delete=models.PROTECT);version=models.PositiveIntegerField(default=1);condiciones=models.JSONField(default=dict);formula=models.JSONField(default=dict);vigente_desde=models.DateField();vigente_hasta=models.DateField(null=True)
class NovedadNomina(Base):empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);concepto=models.ForeignKey(ConceptoNomina,on_delete=models.PROTECT);periodo=models.ForeignKey(PeriodoNomina,on_delete=models.PROTECT);monto=models.DecimalField(max_digits=18,decimal_places=2);estado=models.CharField(max_length=15,default="APROBADA")
class PrestamoEmpleado(Base):empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);principal=models.DecimalField(max_digits=18,decimal_places=2);saldo=models.DecimalField(max_digits=18,decimal_places=2);cuotas=models.PositiveIntegerField()
class CuotaPrestamoEmpleado(models.Model):prestamo=models.ForeignKey(PrestamoEmpleado,on_delete=models.CASCADE,related_name="cuotas_detalle");numero=models.PositiveIntegerField();monto=models.DecimalField(max_digits=18,decimal_places=2);pagada=models.BooleanField(default=False)
class EmbargoEmpleado(Base):empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);monto=models.DecimalField(max_digits=18,decimal_places=2);saldo=models.DecimalField(max_digits=18,decimal_places=2);referencia=models.CharField(max_length=80)
class Nomina(Base):numero=models.CharField(max_length=30);periodo=models.OneToOneField(PeriodoNomina,on_delete=models.PROTECT);estado=models.CharField(max_length=15,default="BORRADOR");total_ingresos=models.DecimalField(max_digits=18,decimal_places=2,default=0);total_deducciones=models.DecimalField(max_digits=18,decimal_places=2,default=0);total_neto=models.DecimalField(max_digits=18,decimal_places=2,default=0);snapshot_reglas=models.JSONField(default=dict)
class DetalleNominaEmpleado(models.Model):nomina=models.ForeignKey(Nomina,on_delete=models.CASCADE,related_name="detalles");empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);ingresos=models.DecimalField(max_digits=18,decimal_places=2);deducciones=models.DecimalField(max_digits=18,decimal_places=2);aportes=models.DecimalField(max_digits=18,decimal_places=2);neto=models.DecimalField(max_digits=18,decimal_places=2)
class LineaDetalleNomina(models.Model):detalle=models.ForeignKey(DetalleNominaEmpleado,on_delete=models.CASCADE,related_name="lineas");concepto=models.ForeignKey(ConceptoNomina,on_delete=models.PROTECT);monto=models.DecimalField(max_digits=18,decimal_places=2);snapshot=models.JSONField(default=dict)
class ReciboNomina(models.Model):detalle=models.OneToOneField(DetalleNominaEmpleado,on_delete=models.PROTECT);numero=models.CharField(max_length=30);archivo=models.FileField(upload_to="nomina/recibos/",blank=True)
class LiquidacionLaboral(Base):empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);fecha=models.DateField();total=models.DecimalField(max_digits=18,decimal_places=2);estado=models.CharField(max_length=15,default="BORRADOR")
class PrestacionLaboral(models.Model):liquidacion=models.ForeignKey(LiquidacionLaboral,on_delete=models.CASCADE,related_name="prestaciones");tipo=models.CharField(max_length=30);monto=models.DecimalField(max_digits=18,decimal_places=2)
class RegaliaPascual(Base):empleado=models.ForeignKey("rrhh.Empleado",on_delete=models.PROTECT);anio=models.PositiveIntegerField();monto=models.DecimalField(max_digits=18,decimal_places=2)
class HistorialNomina(models.Model):nomina=models.ForeignKey(Nomina,on_delete=models.CASCADE,related_name="historial");estado_anterior=models.CharField(max_length=15);estado_nuevo=models.CharField(max_length=15);fecha=models.DateTimeField(auto_now_add=True)
